/* XDE's notes are retrieved locally; they are data, never executable instructions. */
(()=>{'use strict';let entries=null,promise=null,last=null;const norm=v=>String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();const stop=new Set('a an the this that it is are was my i to of on in for at after when with and or game gta ios iphone ipad mac crash crashes crashing not can cant does doesnt please help fix me'.split(' '));const alias={layar:'screen',hitam:'black',macet:'stuck',beku:'freeze',mogok:'freeze',panas:'hot',uang:'money',hilang:'missing',kamera:'camera',foto:'photo',terowongan:'tunnel',garasi:'garage',berhenti:'freeze',keluar:'crash',gagal:'failed',memori:'memory',arsip:'archive',rusak:'broken',ngecrash:'crash',ngelag:'lag',menabrak:'crash',setelah:'after',memuat:'loading',menyetel:'settings',refleksi:'reflection',bayangan:'shadows'};const tokens=v=>[...new Set(norm(v).split(' ').flatMap(t=>[t,alias[t]]).filter(t=>t&&t.length>1&&!stop.has(t)))];
async function load(){if(!promise)promise=fetch('knowledge/kb.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{entries=data.filter(e=>e&&typeof e.id==='string'&&typeof e.title==='string'&&Array.isArray(e.player_fix));return entries;}).catch(()=>{promise=null;return [];});return promise;}
function rank(data,q){const n=norm(q),qt=tokens(q);const df=new Map();data.forEach(e=>new Set(tokens([e.title,...e.symptoms,...e.log_signatures].join(' '))).forEach(t=>df.set(t,(df.get(t)||0)+1)));return data.filter(e=>e.kind!=='reference').map(e=>{const fields=[e.title,...e.symptoms].map(norm),all=tokens(fields.join(' '));let score=0,hits=0,signature=false;for(const raw of e.log_signatures){const s=norm(raw);if(s.length>=9&&n.includes(s)&&!['read from 0x0'].includes(raw)){score+=65;signature=true;}}for(const t of qt){if(all.includes(t)){score+=Math.log(1+data.length/(df.get(t)||1))*2;hits++;}}for(const f of fields)if(f.length>12&&(n.includes(f)||f.includes(n)&&n.length>18))score+=18;if(/\bmac\b|macos/.test(n)&&!e.platforms.includes('macOS'))score-=14;if(/iphone|ipad|ios/.test(n)&&e.platforms.length===1&&e.platforms.includes('macOS'))score-=14;return {e,score,hits,signature};}).sort((a,b)=>b.score-a.score);}
function status(e){if(e.released===false)return 'Not released: the referenced fix is a test build. Use the workaround below; do not assume this is in the public release.';if(e.still_open)return 'Still open or under investigation in this knowledge snapshot.';if(e.released===true)return 'Fix recorded as released in these developer notes.';return 'Status: '+e.status+'.';}
function result(e,signature){const steps=e.player_fix.filter(s=>!(e.released===false&&/from the 27 oct launcher update on/i.test(s)));const text=[e.title,window.FranklinSupportContext?.summary(),'Developer notes · '+e.id+' · 27 Oct 2026',signature?'Your text matches a recorded log signature. Confirm the build and context before treating this as the cause.':'This may match the reported symptom. It is not a confirmed diagnosis.',status(e),e.cause,'What to do:\n'+steps.map((s,i)=>`${i+1}. ${s}`).join('\n'),e.fixed_in?'Build / fix scope: '+e.fixed_in:'',e.still_open?'If this persists, include your device, OS version, build, and the whole Logs folder when contacting the community.':''].filter(Boolean).join('\n\n');last=e.id;return{text,topic:'developer-troubleshooting',grounded:true,knowledgeId:e.id,discord:e.still_open,suggestions:['Where can I find the logs?','How do I identify my build?']};}
async function answer(raw){const generation=window.FranklinSession?.generation;const q=String(raw||'').trim().slice(0,32000);if(!q)return null;const contextReply=await window.FranklinSupportContext?.consume(q);if(contextReply)return contextReply;const data=await load();if(generation!==window.FranklinSession?.generation)return null;if(!data.length)return null;const n=norm(q);if(/^(still|same issue|same problem|it still crashes|masih|masih sama|masih crash)/.test(n)&&last){const e=data.find(e=>e.id===last);if(e)return{...result(e,false),text:'If those steps did not resolve it, please share the device, OS version, exact build, and the whole Logs folder with the community. The earlier match is not a confirmed cause.\n\nPrevious case: '+e.title,discord:true};}
const logInput=/[\r\n]/.test(q)||/sample count|critical archive|game hung|memory:\s*footprint|SIGSEGV|SIGTRAP/i.test(q);let ref=null;if(!logInput&&/where.*logs|find.*logs|lokasi.*log|logs folder/.test(n))ref='REF-01';if(!logInput&&/identify.*build|which build/.test(n))ref='REF-02';if(ref==='REF-02'&&window.FranklinSupportContext)return {text:'Use Change in the support session bar to select your app build, or paste the GTA5 UUID from the first lines of your log. You can also attach run.log so the build can be matched against the developer list. Current support details: '+window.FranklinSupportContext.summary(),grounded:true,topic:'support-context'};if(ref){const e=data.find(e=>e.id===ref);return {...result(e,false),text:[e.title,'XDE notes · '+e.id,...e.player_fix.map((s,i)=>`${i+1}. ${s}`)].join('\n\n')};}
const ranked=rank(data,q),best=ranked[0],next=ranked[1];if(best?.signature&&next?.signature&&best.score-next.score<12)return {text:'This excerpt matches more than one recorded issue: '+best.e.title+'; '+next.e.title+'. Please include the first fatal error and the surrounding lines, the exact action before the failure, and the full Logs folder. I cannot select a single cause reliably from these competing matches.',grounded:true,topic:'developer-triage',discord:true};if(best&&(best.signature||(best.score>=13&&best.hits>=2&&best.score-(next?.score||0)>=2.5)))return result(best.e,best.signature);
if(/crash|freeze|stuck|black screen|force close|ngecrash|macet|layar hitam/.test(n)){return{text:'I need a little more detail to match this reliably.\n\nWhich device and OS version are you using? Which build is installed, and what were you doing just before it failed? Please include the exact error or relevant log lines.\n\nFor iPhone/iPad: Files > On My iPhone/iPad > GTA V > Logs. On Mac: ~/Library/Logs/GTA5. Keep run.log, run.prev.log and crash-*.txt. Check logs for personal information before sharing them.',topic:'developer-triage',grounded:true,suggestions:['How do I identify my build?','Where can I find the logs?']};}return null;}
document.addEventListener('franklin-disconnect',()=>{last=null;});
window.FranklinDeveloperKB={load,answer,rank,status:()=>({loaded:!!entries,entries:entries?.length||0,lastId:last,snapshot:'2026-10-27'})};})();
